def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    adm = ctx.get('admissible', []) or []
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory does not match the target type; do not place it at the destination. Recover by setting it aside if needed, then find the target.'
    elif stage == 'transform' and verb and target:
        if hasact(adm, verb + ' ', target, ''):
            msg = 'The required ' + verb + ' action is available now; use it on the carried ' + target + ' before any put action.'
        else:
            place = 'sinkbasin'
            if verb == 'heat':
                place = 'microwave'
            if verb == 'cool':
                place = 'fridge'
            msg = 'Carry the ' + target + ' to a ' + place + ' and use the ' + verb + ' action before placing it.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the destination with the target; use the put action for ' + target + ' in/on the ' + dest + '.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Keep carrying the ' + target + ' and navigate to a ' + dest + ' for the final put.'
    elif stage == 'take_target' and target:
        msg = 'A target ' + target + ' is available here; take it instead of continuing to search.'
    elif stage == 'find_target' and target and nb.get('placed_count', 0) > 0:
        msg = 'Leave already placed ' + target + ' items at the destination; find another ' + target + ' for the two-object task.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

