    if act.startswith('take ') and target in act and dest and dest in act and nb.get('placed_count', 0) > 0 and not (act.startswith('put ') and target in act and dest in act):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target item that is already placed at the destination. Continue with the remaining subgoal instead.'}
    if act.startswith('put ') and dest and dest in act and not nb.get('transformed') and not (act.startswith(verb + ' ') and target in act):
        return {'kind': 'block_and_prompt', 'message': 'The target still needs the required ' + verb + ' step before being put in/on the ' + dest + '.'}
    return None
